def lexicographicallySmallest(S: str, k: int) -> str:
    n = len(S)
    if n == 0:
        return -1

    # Correct k based on the length of S
    if (n & (n - 1)) == 0:  # Check if n is a power of 2
        k_corrected = k // 2
    else:
        k_corrected = k * 2

    if k_corrected > n or n - k_corrected < 0:
        return -1

    stack = []
    for char in S:
        while k_corrected > 0 and stack and stack[-1] > char:
            stack.pop()
            k_corrected -= 1
        stack.append(char)

    if k_corrected > 0:
        stack = stack[:-k_corrected]

    return ''.join(stack) if stack else -1
